      SUBROUTINE OCTUPLCC     CALCULATES THIRD-ORDER PARTIAL DERIVATIVES FOR AN OCTUPOLEC      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM4C.CIN'      INCLUDE 'U.CIN'C-------------------------------------------------------------------------------      W2 = K3      S = - 0.5*W2*L**2      U(1,1) = S      U(2,1) = 2.0*S/L      U(3,10) = S      U(4,10) = 2.0*S/L      S = - .5*W2*L**3      U(1,2) = S      U(2,2) = 3.*S/L      U(3,16) = S      U(4,16) = 3.0*S/L      S = - 0.25*W2*L**4      U(1,3) = S      U(2,3) = 4.0*S/L      U(3,19) = S      U(4,19) = 4.0*S/L      S = - .05*W2*L**5      U(1,4) = S      U(2,4) = 5.0*S/L      U(3,20) = S      U(4,20) = 5.0*S/L      S = 1.5*W2*L**2      U(1,8) = S      U(2,8) = 2.0*S/L      U(3,5) = S      U(4,5) = 2.0*S/L      S = W2*L**3      U(1,14) = S      U(2,14) = 3.0*S/L      U(3,6) = S      U(4,6) = 3.0*S/L      S = 0.25*W2*L**4      U(1,17) = S      U(2,17) = 4.0*S/L      U(3,7) = S      U(4,7) = 4.0*S/L      S = .5*W2*L**3      U(1,9) = S      U(2,9) = 3.0*S/L      U(3,11) = S      U(4,11) = 3.0*S/L      S = .5*W2*L**4      U(1,15) = S      U(2,15) = 4.0*S/L      U(3,12) = S      U(4,12) = 4.0*S/L      S = 0.15*W2*L**5      U(1,18) = S      U(2,18) = 5.0*S/L      U(3,13) = S      U(4,13) = 5.0*S/L      RETURN      END